import{_ as o,a as n,c as s,ac as a}from"./chunks/framework.BSuaGltH.js";const u=JSON.parse('{"title":"第三册：培养技能 · 全册短语与句型 · 第24–48课","description":"按课次汇总短语用法与原创句型，链接对应课时。","frontmatter":{"title":"第三册：培养技能 · 全册短语与句型 · 第24–48课","description":"按课次汇总短语用法与原创句型，链接对应课时。","splitFrom":"life/english/new-concept/book-3/phrases.md","showdocs":{"topics":[{"id":"english","title":"英语","link":"/topics/english/"}],"kind":"句法与表达查阅","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"第三册：培养技能 · 全册短语与句型","summary":"按课次汇总短语用法与原创句型，链接对应课时。","status":"active","related":[{"title":"程序员英语 01：学习路线与能力自测","link":"/life/english/programmer/overview","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 02：技术词汇与句子骨架","link":"/life/english/programmer/vocabulary","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 03：读懂文档中的条件与约束","link":"/life/english/programmer/reading-docs","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 04：读报错、搜索与求助","link":"/life/english/programmer/errors-search","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 05：写 Issue、Commit 与 PR","link":"/life/english/programmer/issue-pr","kind":"路线与能力起点","scope":"general","audience":"general"}],"prev":{"text":"第三册：培养技能 · 全册短语与句型 · 第1–23课","link":"/life/english/new-concept/book-3/phrases-part-01"},"next":{"text":"第三册：培养技能 · 全册短语与句型 · 第49–60课","link":"/life/english/new-concept/book-3/phrases-part-03"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"第三册：培养技能 · 全册短语与句型 · 第1–23课","link":"/life/english/new-concept/book-3/phrases-part-01"},"next":{"text":"第三册：培养技能 · 全册短语与句型 · 第49–60课","link":"/life/english/new-concept/book-3/phrases-part-03"}},"headers":[],"relativePath":"life/english/new-concept/book-3/phrases-part-02.md","filePath":"life/english/new-concept/book-3/phrases-part-02.md"}'),l={name:"life/english/new-concept/book-3/phrases-part-02.md"};function t(i,e,r,h,p,c){return n(),s("div",null,[...e[0]||(e[0]=[a('<h1 id="第三册-培养技能-·-全册短语与句型-·-第24–48课" tabindex="-1">第三册：培养技能 · 全册短语与句型 · 第24–48课 <a class="header-anchor" href="#第三册-培养技能-·-全册短语与句型-·-第24–48课" aria-label="Permalink to &quot;第三册：培养技能 · 全册短语与句型 · 第24–48课&quot;">​</a></h1><p><a href="/life/english/new-concept/book-3/phrases">返回分篇目录</a></p><p><a href="/life/english/new-concept/book-3/overview">本册介绍</a> · <a href="/life/english/new-concept/book-3/contents">全册课程目录</a> · <a href="/life/english/new-concept/book-3/grammar">全册语法总结</a> · <a href="/life/english/new-concept/book-3/vocabulary">全册单词总结</a> · <a href="/life/english/new-concept/book-3/phrases">全册短语与句型</a> · <a href="/life/english/new-concept/book-3/mistakes">全册易错点</a> · <a href="/life/english/new-concept/book-3/review">综合复习与自测</a></p><h2 id="lesson-24-·-同位语从句与定语从句" tabindex="-1">Lesson 24 · 同位语从句与定语从句 <a class="header-anchor" href="#lesson-24-·-同位语从句与定语从句" aria-label="Permalink to &quot;Lesson 24 · 同位语从句与定语从句 {#lesson-24-·-同位语从句与定语从句}&quot;">​</a></h2><ul><li>keep something to oneself — 不向别人透露某事</li><li>come out — 秘密或真相被公开</li></ul><p><strong>句型示范：</strong> The discovery that the letter was unsigned raised new questions.</p><p>that the letter was unsigned 说明 discovery 的具体内容；从句不缺主语或表语。</p><p><a href="/life/english/new-concept/book-3/unit-02/lesson-024">进入本课</a></p><h2 id="lesson-25-·-过去完成进行时" tabindex="-1">Lesson 25 · 过去完成进行时 <a class="header-anchor" href="#lesson-25-·-过去完成进行时" aria-label="Permalink to &quot;Lesson 25 · 过去完成进行时 {#lesson-25-·-过去完成进行时}&quot;">​</a></h2><ul><li>make good progress — 进展顺利</li><li>against the wind — 逆风而行</li></ul><p><strong>句型示范：</strong> The crew had been sailing for six hours when the wind finally changed.</p><p>had been sailing 强调风变前的持续过程；when 从句提供过去参照点。</p><p><a href="/life/english/new-concept/book-3/unit-02/lesson-025">进入本课</a></p><h2 id="lesson-26-·-too-与-enough-的位置" tabindex="-1">Lesson 26 · too 与 enough 的位置 <a class="header-anchor" href="#lesson-26-·-too-与-enough-的位置" aria-label="Permalink to &quot;Lesson 26 · too 与 enough 的位置 {#lesson-26-·-too-与-enough-的位置}&quot;">​</a></h2><ul><li>make room for — 腾出空间容纳</li><li>in good condition — 状态良好</li></ul><p><strong>句型示范：</strong> The tin is wide enough to hold the cards, but it is too shallow for the wooden pieces.</p><p>enough 在 wide 后；too 在 shallow 前；两个评价分别针对不同物品。</p><p><a href="/life/english/new-concept/book-3/unit-02/lesson-026">进入本课</a></p><h2 id="lesson-27-·-不定代词的后置修饰" tabindex="-1">Lesson 27 · 不定代词的后置修饰 <a class="header-anchor" href="#lesson-27-·-不定代词的后置修饰" aria-label="Permalink to &quot;Lesson 27 · 不定代词的后置修饰 {#lesson-27-·-不定代词的后置修饰}&quot;">​</a></h2><ul><li>do without — 无某物也能应付</li><li>live on — 依靠某收入或食物生活</li></ul><p><strong>句型示范：</strong> We found nothing expensive in the cabin, but there was everything we needed.</p><p>expensive 后置修饰 nothing；everything 后接省略宾语关系词的限定从句 we needed。</p><p><a href="/life/english/new-concept/book-3/unit-02/lesson-027">进入本课</a></p><h2 id="lesson-28-·-条件句中的礼貌距离" tabindex="-1">Lesson 28 · 条件句中的礼貌距离 <a class="header-anchor" href="#lesson-28-·-条件句中的礼貌距离" aria-label="Permalink to &quot;Lesson 28 · 条件句中的礼貌距离 {#lesson-28-·-条件句中的礼貌距离}&quot;">​</a></h2><ul><li>knock off — 从价格中减去某金额</li><li>walk away — 离开交易或谈判，不接受条件</li></ul><p><strong>句型示范：</strong> If you included the carrying case, I would consider paying the full price.</p><p>included 与 would consider 构成试探性条件；consider 不等于作出购买承诺。</p><p><a href="/life/english/new-concept/book-3/unit-02/lesson-028">进入本课</a></p><h2 id="lesson-29-·-whether-从句与选择范围" tabindex="-1">Lesson 29 · whether 从句与选择范围 <a class="header-anchor" href="#lesson-29-·-whether-从句与选择范围" aria-label="Permalink to &quot;Lesson 29 · whether 从句与选择范围 {#lesson-29-·-whether-从句与选择范围}&quot;">​</a></h2><ul><li>take something seriously — 认真对待某事</li><li>at someone&#39;s expense — 以让某人难堪为代价</li></ul><p><strong>句型示范：</strong> Whether the joke works depends partly on what the audience already knows.</p><p>whether 从句整体作主语，谓语为单数 depends；what 从句作 on 的宾语。</p><p><a href="/life/english/new-concept/book-3/unit-02/lesson-029">进入本课</a></p><h2 id="lesson-30-·-情态动词加完成式推断" tabindex="-1">Lesson 30 · 情态动词加完成式推断 <a class="header-anchor" href="#lesson-30-·-情态动词加完成式推断" aria-label="Permalink to &quot;Lesson 30 · 情态动词加完成式推断 {#lesson-30-·-情态动词加完成式推断}&quot;">​</a></h2><ul><li>account for — 解释现象的原因</li><li>rule out — 排除一种可能</li></ul><p><strong>句型示范：</strong> Someone must have opened the cupboard, because the flour had been moved.</p><p>must have opened 是基于线索的推断，because 从句给出依据；推断仍不同于亲眼观察。</p><p><a href="/life/english/new-concept/book-3/unit-02/lesson-030">进入本课</a></p><h2 id="lesson-31-·-非限定性定语从句" tabindex="-1">Lesson 31 · 非限定性定语从句 <a class="header-anchor" href="#lesson-31-·-非限定性定语从句" aria-label="Permalink to &quot;Lesson 31 · 非限定性定语从句 {#lesson-31-·-非限定性定语从句}&quot;">​</a></h2><ul><li>have a habit of — 有做某事的习惯，后接 ing</li><li>be fond of — 喜欢，后接名词或动名词</li></ul><p><strong>句型示范：</strong> Mr Vale, who repairs clocks for fun, keeps a tiny workshop in his kitchen.</p><p>who 从句补充已明确人物的爱好；主句骨架为 Mr Vale keeps a tiny workshop。</p><p><a href="/life/english/new-concept/book-3/unit-02/lesson-031">进入本课</a></p><h2 id="lesson-32-·-现在完成时被动" tabindex="-1">Lesson 32 · 现在完成时被动 <a class="header-anchor" href="#lesson-32-·-现在完成时被动" aria-label="Permalink to &quot;Lesson 32 · 现在完成时被动 {#lesson-32-·-现在完成时被动}&quot;">​</a></h2><ul><li>come across — 偶然发现</li><li>so far — 到目前为止，常与完成时配合</li></ul><p><strong>句型示范：</strong> Three wooden beams have been recovered, but the vessel has not yet been identified.</p><p>have been recovered 对应复数 beams；has not yet been identified 对应单数 vessel。</p><p><a href="/life/english/new-concept/book-3/unit-02/lesson-032">进入本课</a></p><h2 id="lesson-33-·-否定副词前置倒装" tabindex="-1">Lesson 33 · 否定副词前置倒装 <a class="header-anchor" href="#lesson-33-·-否定副词前置倒装" aria-label="Permalink to &quot;Lesson 33 · 否定副词前置倒装 {#lesson-33-·-否定副词前置倒装}&quot;">​</a></h2><ul><li>to one&#39;s relief — 令某人宽慰的是</li><li>not until — 直到……才，注意倒装位置</li></ul><p><strong>句型示范：</strong> Never had I seen the station so quiet before that morning.</p><p>never 前置使 had 提到 I 前；seen 保持过去分词，before that morning 给出过去参照点。</p><p><a href="/life/english/new-concept/book-3/unit-02/lesson-033">进入本课</a></p><h2 id="lesson-34-·-分词状语的逻辑主语" tabindex="-1">Lesson 34 · 分词状语的逻辑主语 <a class="header-anchor" href="#lesson-34-·-分词状语的逻辑主语" aria-label="Permalink to &quot;Lesson 34 · 分词状语的逻辑主语 {#lesson-34-·-分词状语的逻辑主语}&quot;">​</a></h2><ul><li>by chance — 偶然地</li><li>catch one&#39;s eye — 引起注意</li></ul><p><strong>句型示范：</strong> Looking beneath the frame, Maya noticed a small handwritten label.</p><p>Looking 的逻辑主语为 Maya，与主句一致；分词短语交代发现时的动作背景。</p><p><a href="/life/english/new-concept/book-3/unit-02/lesson-034">进入本课</a></p><h2 id="lesson-35-·-情态动词的被动结构" tabindex="-1">Lesson 35 · 情态动词的被动结构 <a class="header-anchor" href="#lesson-35-·-情态动词的被动结构" aria-label="Permalink to &quot;Lesson 35 · 情态动词的被动结构 {#lesson-35-·-情态动词的被动结构}&quot;">​</a></h2><ul><li>take into account — 考虑相关因素</li><li>give someone a chance — 给某人机会</li></ul><p><strong>句型示范：</strong> Both statements should be examined before a decision is announced.</p><p>should be examined 为建议性被动，before 后 is announced 描述流程中的另一步。</p><p><a href="/life/english/new-concept/book-3/unit-02/lesson-035">进入本课</a></p><h2 id="lesson-36-·-so-与-such-的结果结构" tabindex="-1">Lesson 36 · so 与 such 的结果结构 <a class="header-anchor" href="#lesson-36-·-so-与-such-的结果结构" aria-label="Permalink to &quot;Lesson 36 · so 与 such 的结果结构 {#lesson-36-·-so-与-such-的结果结构}&quot;">​</a></h2><ul><li>by coincidence — 碰巧</li><li>run into — 偶然遇见某人</li></ul><p><strong>句型示范：</strong> It was such an unexpected meeting that neither of us spoke for a moment.</p><p>such 修饰 an unexpected meeting 这一名词短语；that 从句表达惊讶造成的反应。</p><p><a href="/life/english/new-concept/book-3/unit-02/lesson-036">进入本课</a></p><h2 id="lesson-37-·-by、until-与时刻表现在时" tabindex="-1">Lesson 37 · by、until 与时刻表现在时 <a class="header-anchor" href="#lesson-37-·-by、until-与时刻表现在时" aria-label="Permalink to &quot;Lesson 37 · by、until 与时刻表现在时 {#lesson-37-·-by、until-与时刻表现在时}&quot;">​</a></h2><ul><li>on time — 按预定时间</li><li>in time for — 来得及参加或赶上</li></ul><p><strong>句型示范：</strong> We must reach the platform by six, although the train does not leave until ten past.</p><p>by six 给到达截止时间；not ... until ten past 给列车最早实际离开时间。</p><p><a href="/life/english/new-concept/book-3/unit-02/lesson-037">进入本课</a></p><h2 id="lesson-38-·-目的不定式与-for-doing" tabindex="-1">Lesson 38 · 目的不定式与 for doing <a class="header-anchor" href="#lesson-38-·-目的不定式与-for-doing" aria-label="Permalink to &quot;Lesson 38 · 目的不定式与 for doing {#lesson-38-·-目的不定式与-for-doing}&quot;">​</a></h2><ul><li>keep track of — 持续记录并掌握进度</li><li>in order to — 为了做某事</li></ul><p><strong>句型示范：</strong> The group marked a stone each evening to keep track of passing days.</p><p>marked 为主要动作，to keep track of 为目的；each evening 说明重复频率。</p><p><a href="/life/english/new-concept/book-3/unit-02/lesson-038">进入本课</a></p><h2 id="lesson-39-·-不定式后置修饰与介词" tabindex="-1">Lesson 39 · 不定式后置修饰与介词 <a class="header-anchor" href="#lesson-39-·-不定式后置修饰与介词" aria-label="Permalink to &quot;Lesson 39 · 不定式后置修饰与介词 {#lesson-39-·-不定式后置修饰与介词}&quot;">​</a></h2><ul><li>take precautions — 采取预防措施</li><li>keep an eye on — 留意某人或某事</li></ul><p><strong>句型示范：</strong> We had a reliable guide to consult and a marked path to follow.</p><p>consult 与 follow 都直接带宾语，因此不定式末尾无需额外介词；guide 与 path 分别为其对象。</p><p><a href="/life/english/new-concept/book-3/unit-02/lesson-039">进入本课</a></p><h2 id="lesson-40-·-反身代词与相互代词" tabindex="-1">Lesson 40 · 反身代词与相互代词 <a class="header-anchor" href="#lesson-40-·-反身代词与相互代词" aria-label="Permalink to &quot;Lesson 40 · 反身代词与相互代词 {#lesson-40-·-反身代词与相互代词}&quot;">​</a></h2><ul><li>in person — 亲自到场</li><li>mistake A for B — 把A误认为B</li></ul><p><strong>句型示范：</strong> The two actors introduced themselves before they introduced each other to the director.</p><p>themselves 回指各自，each other 表示相互对象；两个短语改变动作方向。</p><p><a href="/life/english/new-concept/book-3/unit-02/lesson-040">进入本课</a></p><h2 id="lesson-41-·-while-与-whereas-的对照" tabindex="-1">Lesson 41 · while 与 whereas 的对照 <a class="header-anchor" href="#lesson-41-·-while-与-whereas-的对照" aria-label="Permalink to &quot;Lesson 41 · while 与 whereas 的对照 {#lesson-41-·-while-与-whereas-的对照}&quot;">​</a></h2><ul><li>in contrast — 相比之下，引出差异</li><li>far from — 远非，也可表示距离很远</li></ul><p><strong>句型示范：</strong> The village is quiet after sunset, whereas the market town remains busy until midnight.</p><p>whereas 对照两个地方在夜间的活动状态，不表示一个事件发生在另一个事件期间。</p><p><a href="/life/english/new-concept/book-3/unit-03/lesson-041">进入本课</a></p><h2 id="lesson-42-·-独立主格的独立主语" tabindex="-1">Lesson 42 · 独立主格的独立主语 <a class="header-anchor" href="#lesson-42-·-独立主格的独立主语" aria-label="Permalink to &quot;Lesson 42 · 独立主格的独立主语 {#lesson-42-·-独立主格的独立主语}&quot;">​</a></h2><ul><li>make one&#39;s way — 设法前进</li><li>in single file — 排成单列</li></ul><p><strong>句型示范：</strong> The main passage blocked, the team returned to the entrance.</p><p>the main passage 为独立结构主语，blocked 表被动状态；主句主语为 the team。</p><p><a href="/life/english/new-concept/book-3/unit-03/lesson-042">进入本课</a></p><h2 id="lesson-43-·-provided-that-与-unless" tabindex="-1">Lesson 43 · provided that 与 unless <a class="header-anchor" href="#lesson-43-·-provided-that-与-unless" aria-label="Permalink to &quot;Lesson 43 · provided that 与 unless {#lesson-43-·-provided-that-与-unless}&quot;">​</a></h2><ul><li>subject to — 受某条件限制</li><li>in the event of — 如果发生某事件</li></ul><p><strong>句型示范：</strong> In this fictional scheme, repairs are covered provided that the damage is reported within a week.</p><p>provided that 引出必要条件；within a week 给出时间限制，句子没有描述现实产品。</p><p><a href="/life/english/new-concept/book-3/unit-03/lesson-043">进入本课</a></p><h2 id="lesson-44-·-平行结构与-not-only" tabindex="-1">Lesson 44 · 平行结构与 not only <a class="header-anchor" href="#lesson-44-·-平行结构与-not-only" aria-label="Permalink to &quot;Lesson 44 · 平行结构与 not only {#lesson-44-·-平行结构与-not-only}&quot;">​</a></h2><ul><li>take into consideration — 纳入考虑</li><li>door to door — 从出发门口到目的地门口</li></ul><p><strong>句型示范：</strong> The night train offers both a quiet place to sleep and a direct route to the city centre.</p><p>both ... and 连接两个名词短语，均为 offers 的宾语，语法层级一致。</p><p><a href="/life/english/new-concept/book-3/unit-03/lesson-044">进入本课</a></p><h2 id="lesson-45-·-报告动词及其结构" tabindex="-1">Lesson 45 · 报告动词及其结构 <a class="header-anchor" href="#lesson-45-·-报告动词及其结构" aria-label="Permalink to &quot;Lesson 45 · 报告动词及其结构 {#lesson-45-·-报告动词及其结构}&quot;">​</a></h2><ul><li>draw attention to — 引起对某问题的关注</li><li>make a distinction — 作出区分</li></ul><p><strong>句型示范：</strong> The reporter stated the figures, while the campaigner claimed that they showed a wider problem.</p><p>stated 与 claimed 区分陈述和观点；they 回指 figures，后半结论归属于 campaigner。</p><p><a href="/life/english/new-concept/book-3/unit-03/lesson-045">进入本课</a></p><h2 id="lesson-46-·-过去能力与一次成功" tabindex="-1">Lesson 46 · 过去能力与一次成功 <a class="header-anchor" href="#lesson-46-·-过去能力与一次成功" aria-label="Permalink to &quot;Lesson 46 · 过去能力与一次成功 {#lesson-46-·-过去能力与一次成功}&quot;">​</a></h2><ul><li>put together — 组装</li><li>call in — 请某专业人员前来</li></ul><p><strong>句型示范：</strong> After several careful attempts, I managed to remove the damaged screw.</p><p>managed to remove 表示实际成功，after 短语解释此前有困难和尝试。</p><p><a href="/life/english/new-concept/book-3/unit-03/lesson-046">进入本课</a></p><h2 id="lesson-47-·-because、therefore-与因果关系" tabindex="-1">Lesson 47 · because、therefore 与因果关系 <a class="header-anchor" href="#lesson-47-·-because、therefore-与因果关系" aria-label="Permalink to &quot;Lesson 47 · because、therefore 与因果关系 {#lesson-47-·-because、therefore-与因果关系}&quot;">​</a></h2><ul><li>at the expense of — 以牺牲某方面为代价</li><li>contribute to — 促成某结果，通常不表示唯一原因</li></ul><p><strong>句型示范：</strong> The courtyard remained noisy after midnight; therefore, several residents moved their bedrooms to the rear.</p><p>分号分开完整分句，therefore 标明结果；several 限定受影响者，未概括为所有住户。</p><p><a href="/life/english/new-concept/book-3/unit-03/lesson-047">进入本课</a></p><h2 id="lesson-48-·-地点前置的完全倒装" tabindex="-1">Lesson 48 · 地点前置的完全倒装 <a class="header-anchor" href="#lesson-48-·-地点前置的完全倒装" aria-label="Permalink to &quot;Lesson 48 · 地点前置的完全倒装 {#lesson-48-·-地点前置的完全倒装}&quot;">​</a></h2><ul><li>in the distance — 在远处</li><li>give the impression of — 给人某种印象，未必等于事实</li></ul><p><strong>句型示范：</strong> Beyond the empty square stood a row of houses with closed shutters.</p><p>地点短语前置，stood 在名词主语 a row of houses 之前，构成完全倒装。</p><p><a href="/life/english/new-concept/book-3/unit-03/lesson-048">进入本课</a></p>',128)])])}const f=o(l,[["render",t]]);export{u as __pageData,f as default};
